export function decodeAskUserQuestion(value: unknown): AskUserQuestion {
  if (!isObject(value)) failDecode('AskUserQuestion', 'expected object')
  if (typeof value.id !== 'string') failDecode('AskUserQuestion.id', 'expected string')
  const id = value.id
  if (typeof value.prompt !== 'string') failDecode('AskUserQuestion.prompt', 'expected string')
  const prompt = value.prompt
  if (!Array.isArray(value.options)) failDecode('AskUserQuestion.options', 'expected array')
  const options: string[] = []
  for (let index = 0; index < value.options.length; index += 1) {
    const item = value.options[index]
    if (typeof item !== 'string') failDecode('AskUserQuestion.options' + '[' + String(index) + ']', 'expected string')
    const decoded = item
    options.push(decoded)
  }
  if (typeof value.allowMultiple !== 'boolean') failDecode('AskUserQuestion.allowMultiple', 'expected boolean')
  const allowMultiple = value.allowMultiple
  return { id, prompt, options, allowMultiple }
}

export function decodeAskUserRequest(value: unknown): AskUserRequest {
  if (!isObject(value)) failDecode('AskUserRequest', 'expected object')
  const identity = decodeUiCapabilityIdentity(value.identity)
  if (!Array.isArray(value.questions)) failDecode('AskUserRequest.questions', 'expected array')
  const questions: AskUserQuestion[] = []
  for (let index = 0; index < value.questions.length; index += 1) {
    const item = value.questions[index]
    const decoded = decodeAskUserQuestion(item)
    questions.push(decoded)
  }
  return { identity, questions }
}

