export function decodeRuntimeEvent(value: unknown): RuntimeEvent {
  if (!isObject(value) || typeof value.type !== 'string') {
    failDecode('RuntimeEvent', 'expected object with type')
  }
  switch (value.type) {
    case 'runtime.reset':
      return decodeRuntimeReset(value)
    case 'runtime.run-changed':
      return decodeRunChanged(value)
    case 'runtime.message-started':
      return decodeMessageStarted(value)
    case 'runtime.message-delta':
      return decodeMessageDelta(value)
    case 'runtime.message-block-changed':
      return decodeMessageBlockChanged(value)
    case 'runtime.tool-call-changed':
      return decodeToolCallChanged(value)
    case 'runtime.approval-changed':
      return decodeApprovalChanged(value)
    case 'runtime.ui-capability-changed':
      return decodeUiCapabilityChanged(value)
    case 'runtime.run-completed':
      return decodeRunCompleted(value)
    case 'runtime.session-transcript-committed':
      return decodeSessionTranscriptCommitted(value)
    default:
      failDecode('RuntimeEvent', `unknown type ${String(value.type)}`)
  }
}
